function prep(c){let d=Math.min(devicePixelRatio||1,2),w=c.clientWidth,h=c.clientHeight;if(c.width!==w*d||c.height!==h*d){c.width=w*d;c.height=h*d}let x=c.getContext('2d');x.setTransform(d,0,0,d,0,0);x.clearRect(0,0,w,h);x.fillStyle='#061018';x.fillRect(0,0,w,h);return{x,w,h}}
function history(){let{x,w,h}=prep($('history')),H=dyn.history;if(H.length<2)return;let t0=H[0].t,t1=H[H.length-1].t,zs=H.flatMap(q=>[q.z,q.hubF,q.hubR]),z0=Math.min(...zs)-.03,z1=Math.max(...zs)+.03,X=t=>20+(t-t0)/Math.max(.01,t1-t0)*(w-35),Y=z=>h-20-(z-z0)/Math.max(.01,z1-z0)*(h-45);function plot(key,c){x.strokeStyle=c;x.lineWidth=2;x.beginPath();H.forEach((q,i)=>i?x.lineTo(X(q.t),Y(q[key])):x.moveTo(X(q.t),Y(q[key])));x.stroke()}plot('z','#72e5ff');plot('hubF','#78efb1');plot('hubR','#ffc66c');x.fillStyle='#9bb4c0';x.font='10px ui-monospace';x.fillText('body',14,30);x.fillStyle='#72e5ff';x.fillRect(48,23,18,3);x.fillStyle='#78efb1';x.fillRect(86,23,18,3);x.fillStyle='#9bb4c0';x.fillText('F axle',108,30);x.fillStyle='#ffc66c';x.fillRect(157,23,18,3);x.fillStyle='#9bb4c0';x.fillText('R axle',179,30)}
function patches(){let{x,w,h}=prep($('patches'));function one(M,cx,label){let hull=M.contact.hull||[],sm=M.contact.samples||[],ww=w*.46,hh=h*.75;if(!hull.length){x.fillStyle='#829ca8';x.fillText(label+' no contact',cx-40,h*.5);return}let all=hull.concat(sm.map(q=>[q.x,q.y])),minx=Math.min(...all.map(q=>q[0])),maxx=Math.max(...all.map(q=>q[0])),miny=Math.min(...all.map(q=>q[1])),maxy=Math.max(...all.map(q=>q[1])),sc=Math.min(ww/Math.max(.03,maxx-minx),hh/Math.max(.04,maxy-miny)),X=q=>cx+(q-(minx+maxx)/2)*sc,Y=q=>h*.54-(q-(miny+maxy)/2)*sc,mf=Math.max(1,...sm.map(q=>q.fn));for(let q of sm){let r=2+5*Math.sqrt(q.fn/mf);x.fillStyle=`rgba(100,220,255,${.25+.7*q.fn/mf})`;x.beginPath();x.arc(X(q.x),Y(q.y),r,0,PI*2);x.fill()}x.strokeStyle='#73efad';x.lineWidth=2;x.beginPath();hull.forEach((q,i)=>i?x.lineTo(X(q[0]),Y(q[1])):x.moveTo(X(q[0]),Y(q[1])));x.closePath();x.stroke();x.fillStyle='#dceef5';x.font='10px ui-monospace';x.fillText(label+' '+(M.contact.loadN).toFixed(0)+'N · '+(M.contact.areaM2*1e4).toFixed(1)+'cm²',cx-ww/2,h-13)}one(dyn.front.last,w*.25,'FRONT');one(dyn.rear.last,w*.75,'REAR')}
function energy(){let{x,w,h}=prep($('energy')),E=dyn.last.energy,vals=[['Fork damper',E.forkDamperLossJ],['Rear shock',E.rearDamperLossJ],['System mech loss',E.systemMechanicalLossJ],['Tire+numeric residual',E.tirePlusNumericalResidualJ]],mx=Math.max(1,...vals.map(q=>Math.max(0,q[1]||0)));x.font='11px ui-monospace';vals.forEach((q,i)=>{let y=50+i*42,v=Math.max(0,q[1]||0);x.fillStyle='#18303a';x.fillRect(128,y-14,w-150,18);x.fillStyle=i<2?'#70dfff':i===2?'#78efb1':'#c68cff';x.fillRect(128,y-14,(w-150)*v/mx,18);x.fillStyle='#dceef5';x.fillText(q[0],14,y);x.fillText(v.toFixed(1)+' J',w-76,y)});x.fillStyle='#8ca6b2';x.fillText('Δmechanical '+(E.mechanicalDeltaJ||0).toFixed(1)+' J · tire stored Δ '+(E.tireStoredDeltaJ||0).toFixed(1)+' J',14,h-18)}
